How can I display the list of products and promotions on an HTML page and allow the user to input a promo code and target price range? The page should dynamically calculate and display the total cost after applying any applicable discounts, the number of items in the shopping cart that fall within the specified price range, and the average price per item in the shopping cart. Here is the code for the product and promotion lists:
<div id="products">
  <h2>Products:</h2>
  <ul>
    <li><span class="name">Shirt</span> <span class="price">$25.00</span></li>
    <li><span class="name">Pants</span> <span class="price">$40.00</span></li>
  </ul>
</div>
<div id="promotions">
  <h2>Promotions:</h2>
  <ul>
    <li><span class="promo-code">SAVE10</span> <span class="discount">10%</span></li>
    <li><span class="promo-code">SAVE20</span> <span class="discount">20%</span></li>
  </ul>
</div>
And here is the JavaScript function that calculates the total cost, number of items in the price range, and average price:
function calculateTotalCost(promoCode, targetPriceRange) {
  var productList = [
    { name: "Shirt", price: 25.00 },
    { name: "Pants", price: 40.00 }
  ];
  var promotions = [
    { promoCode: "SAVE10", discount: 0.10 },
    { promoCode: "SAVE20", discount: 0.20 }
  ];
  var totalCost = 0.0;
  var count = 0;
  for (var i = 0; i < productList.length; i++) {
    var product = productList[i];
    totalCost += product.price;
    if (targetPriceRange.contains(product.price)) {
      count += 1;
    }
  }
  if (promoCode) {
    for (var i = 0; i < promotions.length; i++) {
      var promotion = promotions[i];
      if (promotion.promoCode === promoCode) {
        totalCost *= (1 - promotion.discount);
      }
    }
  }
  var averagePrice = totalCost / productList.length;
  return [totalCost, count, averagePrice];
} 
How can I integrate this function with the HTML page to create a dynamic shopping cart experience?

What is the HTML code to create a password generator form that meets the following criteria:
- Allows the user to select the password length (minimum 12 characters)
- Includes checkboxes for selecting at least two uppercase letters, at least two lowercase letters, at least two numbers, and at least two special characters (from a predefined set of characters)
- Includes a button to generate the password using JavaScript
- Displays the generated password in a text input field
[HTML code]:
<form>
  <label for="length">Password length:</label>
  <input type="number" id="length" name="length" min="12" required><br>
  <label>Include:</label><br>
  <input type="checkbox" id="uppercase" name="uppercase" value="uppercase">
  <label for="uppercase">At least 2 uppercase letters</label><br>
  <input type="checkbox" id="lowercase" name="lowercase" value="lowercase">
  <label for="lowercase">At least 2 lowercase letters</label><br>
  <input type="checkbox" id="numbers" name="numbers" value="numbers">
  <label for="numbers">At least 2 numbers</label><br>
  <input type="checkbox" id="special" name="special" value="special">
  <label for="special">At least 2 special characters (!@#$%^&*)</label><br>
  <button type="button" onclick="generatePassword()">Generate Password</button><br>
  <label for="password">Generated Password:</label>
  <input type="text" id="password" name="password" readonly>
</form>
<script>
function generatePassword() {
  var length = document.getElementById("length").value;
  var uppercase = document.getElementById("uppercase").checked;
  var lowercase = document.getElementById("lowercase").checked;
  var numbers = document.getElementById("numbers").checked;
  var special = document.getElementById("special").checked;
  var uppercase_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  var lowercase_chars = "abcdefghijklmnopqrstuvwxyz";
  var number_chars = "0123456789";
  var special_chars = "!@#$%^&*()";
  var all_chars = "";
  var password = "";
  if (uppercase) {
    all_chars += uppercase_chars;
    password += uppercase_chars.charAt(Math.floor(Math.random() * uppercase_chars.length));
    password += uppercase_chars.charAt(Math.floor(Math.random() * uppercase_chars.length));
  }
  if (lowercase) {
    all_chars += lowercase_chars;
    password += lowercase_chars.charAt(Math.floor(Math.random() * lowercase_chars.length));
    password += lowercase_chars.charAt(Math.floor(Math.random() * lowercase_chars.length));
  }
  if (numbers) {
    all_chars += number_chars;
    password += number_chars.charAt(Math.floor(Math.random() * number_chars.length));
    password += number_chars.charAt(Math.floor(Math.random() * number_chars.length));
  }
  if (special) {
    all_chars += special_chars;
    password += special_chars.charAt(Math.floor(Math.random() * special_chars.length));
    password += special_chars.charAt(Math.floor(Math.random() * special_chars.length));
  }
  while (password.length < length) {
    password += all_chars.charAt(Math.floor(Math.random() * all_chars.length));
  }
  password = password.split('').sort(function(){return 0.5-Math.random()}).join('');
  document.getElementById("password").value = password;
}
</script>

