```
// Define the JSON dataset
var data = []byte(`{
    "dataset": [
        {"text": "I love this movie", "label": "subjective"},
        {"text": "The capital of France is Paris", "label": "objective"},
        {"text": "This book is boring", "label": "subjective"},
        {"text": "Water boils at 100 degrees Celsius", "label": "objective"},
        {"text": "I feel tired today", "label": "subjective"},
        {"text": "The Earth revolves around the Sun", "label": "objective"}
    ]
}`)
// Parse the JSON dataset
var obj map[string][]map[string]string
err := json.Unmarshal(data, &obj)
if err != nil {
    panic(err)
}
// Extract the dataset and labels
var dataset []string
var labels []string
for _, item := range obj["dataset"] {
    dataset = append(dataset, item["text"])
    labels = append(labels, item["label"])
}
// Define the vectorizer
vectorizer := NewCountVectorizer()
vectorizer.Fit(dataset)
X, _ := vectorizer.Transform(dataset)
// Define the classifier
clf := NewMultinomialNB()
clf.Fit(X, labels)
// Predict the label for a given statement
statement := "This pizza tastes great"
X_test, _ := vectorizer.Transform([]string{statement})
predictedLabel := clf.Predict(X_test)
// Evaluate the performance of the model using a confusion matrix
confusionMatrix := metrics.ConfusionMatrix(labels, predictedLabel)
fmt.Println("Confusion matrix:", confusionMatrix)
```
