)
func main() {
    sentence := "The antique vase had intricate designs carved into it."
    adjective := "exquisite"

    words := strings.Fields(sentence)
    for i, word := range words {
        stemmed, err := snowball.Stem(word, "english", false)
        if err != nil {
            continue
        }
        if stemmed == "antiqu" {
            words[i+1] = adjective
