  <button type="button" onclick="calculateCarbonFootprint()">Calculate Carbon Footprint</button>
</form>
And here is the JavaScript code to calculate the carbon footprint and display the results:
<script>
function calculateCarbonFootprint() {
  const plasticWeight = document.getElementById("plasticWeight").value;
  const paperWeight = document.getElementById("paperWeight").value;
  const metalWeight = document.getElementById("metalWeight").value;
  const plasticCarbonFootprint = (plasticWeight * 1.8) / 2000;
  const paperCarbonFootprint = (paperWeight * 0.91) / 2000;
  const metalCarbonFootprint = (metalWeight * 2.7) / 2000;
  document.getElementById("plasticCarbonFootprint").innerHTML = "Carbon Footprint of Plastic Straw: " + plasticCarbonFootprint;
  document.getElementById("paperCarbonFootprint").innerHTML = "Carbon Footprint of Paper Straw: " + paperCarbonFootprint;
  document.getElementById("metalCarbonFootprint").innerHTML = "Carbon Footprint of Metal Straw: " + metalCarbonFootprint;
  if (plasticCarbonFootprint < paperCarbonFootprint && plasticCarbonFootprint < metalCarbonFootprint) {
    document.getElementById("lowestCarbonFootprint").innerHTML = "Plastic has the lowest carbon footprint";
  } else if (paperCarbonFootprint < plasticCarbonFootprint && paperCarbonFootprint < metalCarbonFootprint) {
    document.getElementById("lowestCarbonFootprint").innerHTML = "Paper has the lowest carbon footprint";
  } else {
    document.getElementById("lowestCarbonFootprint").innerHTML = "Metal has the lowest carbon footprint";
  }
}
