import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
public class ProfitCalculator {
    public static void main(String[] args) {
        String csvFile = "file.csv";
        String line = "";
        String cvsSplitBy = ",";
        Map<String, Double> totalProfitPerMonth = new HashMap<>();
        double overallProfit = 0;
        try (BufferedReader br = new BufferedReader(new FileReader(csvFile))) {
            // Skip header line
            br.readLine();
            // Loop through each line of data
            while ((line = br.readLine()) != null) {
                String[] row = line.split(cvsSplitBy);
                // Get month and convert income and expenses to doubles
                String month = row[0];
                double income = Double.parseDouble(row[1].substring(1));
                double expenses = Double.parseDouble(row[2].substring(1));
                // Calculate profit and print result
                double profit = income - expenses;
                overallProfit += profit;
                totalProfitPerMonth.put(month, profit);
                if (profit < 0) {
                    System.out.printf("%s: $%.2f *** NEGATIVE PROFIT ***\n", month, profit);
                } else {
                    System.out.printf("%s: $%.2f\n", month, profit);
                }
            }
            // Output total profit per month and overall total profit in JSON format
            System.out.println("{");
            System.out.println("  \"data\": [");
            for (Map.Entry<String, Double> entry : totalProfitPerMonth.entrySet()) {
                System.out.printf("    {\"Month\": \"%s\", \"Total Profit\": \"%.2f\"},\n", entry.getKey(), entry.getValue());
            }
            System.out.printf("    {\"Overall Profit\": \"%.2f\"}\n", overallProfit);
            System.out.println("  ]");
            System.out.println("}");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
